  return API.get(`/${moduleId}`, {
    params: { difficulty },
  });
};

export const submitAnswer = (moduleId: string, data: {
  student_id: number;
  question_id: number;
  answer: string;
}) => {
  return API.post(`/${moduleId}/answer`, data);
};

export default API;

