import axios from "axios";

const API = axios.create({
  baseURL: "http://localhost:5000/api/learning-modules",
});

API.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// Maps backend subtopic names to colors/emojis for display
const TOPIC_META: Record<string, { color: string; icon: string; skill: string }> = {
  "Hosts and access networks": { color: "#7c3aed", icon: "🖥️", skill: "Networking Basics" },
  "Physical media":             { color: "#0891b2", icon: "🔌", skill: "Hardware Concepts" },
  "Packet switching":           { color: "#059669", icon: "📦", skill: "Data Transmission" },
  "Circuit switching":          { color: "#d97706", icon: "🔄", skill: "Network Protocols" },
  "Internet structure":         { color: "#dc2626", icon: "🌐", skill: "Internet Architecture" },
};

function toModule(item: any) {
  const meta = TOPIC_META[item.id] ?? { color: "#7c3aed", icon: "📚", skill: "Computer Networks" };
  return {
    _id: item.id,
    moduleId: item.id,
    title: item.title,
    description: item.description ?? `Learn about ${item.title}`,
    category: item.category ?? "Academic",
    skill: meta.skill,
    level: "Beginner",
    duration: item.estimatedTime ?? 15,
    ageGroups: ["All ages"],
    objectives: [`Understand ${item.title}`],
    steps: ["Read content", "Answer question", "Get feedback"],
    adaptations: ["Text explanations", "Hints available"],
    icon: item.icon ?? meta.icon,
    color: meta.color,
    status: "available",
  };
}

const FALLBACK_MODULES = [
  "Hosts and access networks",
  "Physical media",
  "Packet switching",
  "Circuit switching",
  "Internet structure",
].map((id) =>
  toModule({
    id,
    title: id,
    description: `Learn about ${id}`,
    category: "Academic",
    estimatedTime: 15,
  })
);

export const getLearningModules = (params?: { category?: string; level?: string }) => {
  return API.get("/", { params })
    .then((res) => {
      // Backend returns { data: [...] }, axios wraps that in res.data
      const items: any[] = res.data?.data ?? res.data ?? [];
      return { data: items.map(toModule) };
    })
    .catch(() => {
      // Backend not running — use fallback so cards still appear
      return { data: FALLBACK_MODULES };
    });
};

export const getLearningModule = (moduleId: string, difficulty = "easy") => {
  return API.get(`/${moduleId}`, { params: { difficulty } }).catch(() => {
    return {
      data: {
        id: moduleId,
        title: moduleId,
        content: {
          text: `This module covers ${moduleId}. Read through the material carefully before answering the question.`,
          type: "easy_explanation",
        },
        question: {
          id: `${moduleId}_q1`,
          text: `What is the main concept behind "${moduleId}"?`,
          type: "open_ended",
        },
        hint: { text: `Think about how ${moduleId} relates to networking.` },
        difficulty,
      },
    };
  });
};

export const submitAnswer = (
  moduleId: string,
  data: { student_id: number; question_id: number; answer: string }
) => {
  return API.post(`/${moduleId}/answer`, data).catch(() => {
    // Fallback evaluation when backend is down
    return {
      data: {
        correct: false,
        mastery_score: 0,
        next_difficulty: "easy",
        recommendation: "Backend is not reachable. Start the backend server and try again.",
        correct_answer: "N/A",
      },
    };
  });
};

export default API;

