from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware

from app.database import (
    content_versions_collection,
    questions_collection,
    mastery_state_collection
)

from app.schemas import AnswerRequest


# ============================================================
# CREATE FASTAPI APPLICATION
# ============================================================

app = FastAPI(
    title="Adaptive Learning Platform - Person 2",
    description="MongoDB based answer grading and mastery API",
    version="1.0.0"
)

# Enable CORS for frontend
app.add_middleware(
    CORSMiddleware,
    allow_origins=["http://localhost:5173", "http://localhost:3000", "*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


# ============================================================
# HOME ROUTE
# ============================================================

@app.get("/")
def home():
    return {
        "message": "Person 2 API is running"
    }


# ============================================================
# HEALTH CHECK
# ============================================================

@app.get("/health")
def health():

    try:
        from app.database import client

        # Check MongoDB connection
        client.admin.command("ping")

        return {
            "status": "healthy",
            "mongodb": "connected"
        }

    except Exception as e:

        return {
            "status": "unhealthy",
            "mongodb": "disconnected",
            "error": str(e)
        }


# ============================================================
# POST /answer
# ============================================================

@app.post("/answer")
def submit_answer(request: AnswerRequest):

    # --------------------------------------------------------
    # 1. FIND QUESTION
    # --------------------------------------------------------

    question = questions_collection.find_one(
        {
            "question_id": request.question_id
        }
    )

    if question is None:

        raise HTTPException(
            status_code=404,
            detail="Question not found"
        )


    # --------------------------------------------------------
    # 2. GET CORRECT ANSWER
    # --------------------------------------------------------

    correct_answer = str(
        question["correct_answer"]
    )

    student_answer = str(
        request.answer
    )


    # --------------------------------------------------------
    # 3. NORMALIZE ANSWERS
    # --------------------------------------------------------

    correct_answer = (
        correct_answer
        .strip()
        .lower()
    )

    student_answer = (
        student_answer
        .strip()
        .lower()
    )


    # --------------------------------------------------------
    # 4. CHECK ANSWER
    # --------------------------------------------------------

    correct = (
        student_answer == correct_answer
    )


    # --------------------------------------------------------
    # 5. FIND CONTENT VERSION
    # --------------------------------------------------------

    content = content_versions_collection.find_one(
        {
            "content_version_id":
                question["content_version_id"]
        }
    )

    if content is None:

        raise HTTPException(
            status_code=404,
            detail="Content version not found"
        )


    # --------------------------------------------------------
    # 6. GET SUBTOPIC ID
    # --------------------------------------------------------

    subtopic_id = content["subtopic_id"]


    # --------------------------------------------------------
    # 7. FIND MASTERY FOR THIS STUDENT + SUBTOPIC
    # --------------------------------------------------------

    mastery = mastery_state_collection.find_one(
        {
            "student_id": request.student_id,
            "subtopic_id": subtopic_id
        }
    )


    # --------------------------------------------------------
    # 8. CREATE MASTERY RECORD IF IT DOES NOT EXIST
    # --------------------------------------------------------

    if mastery is None:

        # Starting mastery score
        mastery_score = 0

        mastery_state_collection.insert_one(
            {
                "student_id": request.student_id,
                "subtopic_id": subtopic_id,
                "mastery_score": mastery_score
            }
        )

    else:

        # Existing student's score
        mastery_score = mastery.get(
            "mastery_score",
            0
        )


    # --------------------------------------------------------
    # 9. UPDATE SCORE
    # --------------------------------------------------------

    if correct:

        mastery_score += 10

    else:

        mastery_score -= 10


    # --------------------------------------------------------
    # 10. LIMIT SCORE BETWEEN 0 AND 100
    # --------------------------------------------------------

    mastery_score = max(
        0,
        min(
            100,
            mastery_score
        )
    )


    # --------------------------------------------------------
    # 11. UPDATE ONLY THIS STUDENT'S RECORD
    # --------------------------------------------------------

    mastery_state_collection.update_one(
        {
            "student_id": request.student_id,
            "subtopic_id": subtopic_id
        },
        {
            "$set": {
                "mastery_score": mastery_score
            }
        }
    )


    # --------------------------------------------------------
    # 12. RETURN RESULT
    # --------------------------------------------------------

    return {
        "student_id": request.student_id,
        "question_id": request.question_id,
        "correct": correct,
        "mastery_score": mastery_score
    }


# ============================================================
# GET ALL LEARNING MODULES (SUBTOPICS)
# ============================================================

@app.get("/api/learning-modules")
def get_learning_modules(category: str = "All"):
    """
    Get all available learning modules (subtopics) from content_versions.
    Returns unique subtopics and their metadata.
    """
    try:
        # Get all distinct subtopics
        subtopics = content_versions_collection.distinct("subtopic")

        if not subtopics:
            return {"data": []}

        # Build module objects with metadata
        modules = []
        for subtopic in subtopics:
            # Get one content piece to extract metadata
            content = content_versions_collection.find_one({"subtopic": subtopic})

            if content:
                module = {
                    "id": subtopic,
                    "title": subtopic,
                    "category": category if category != "All" else "Academic",
                    "description": f"Learn about {subtopic}",
                    "difficulty": "beginner",
                    "estimatedTime": 15,
                    "icon": "📚"
                }
                modules.append(module)

        return {"data": modules}

    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Error fetching modules: {str(e)}")


# ============================================================
# GET LEARNING MODULE CONTENT
# ============================================================

@app.get("/api/learning-modules/{module_id}")
def get_learning_module_content(module_id: str, difficulty: str = "easy"):
    """
    Get content and question for a specific module at a given difficulty.
    module_id = subtopic name
    """
    try:
        # Determine content type based on difficulty
        if difficulty == "easy":
            content_type = "easy_explanation"
            question_type = "easy_question"
        else:
            content_type = "medium_explanation"
            question_type = "medium_question"

        # Get content
        content = content_versions_collection.find_one({
            "subtopic": module_id,
            "content_type": content_type
        })

        if not content:
            raise HTTPException(status_code=404, detail=f"Content not found for {module_id}")

        # Get question
        question = content_versions_collection.find_one({
            "subtopic": module_id,
            "content_type": question_type
        })

        # Get hint
        hint = content_versions_collection.find_one({
            "subtopic": module_id,
            "content_type": "hint"
        })

        response = {
            "id": module_id,
            "title": module_id,
            "content": {
                "text": content.get("content_text", "") if content else "",
                "type": content_type
            },
            "question": {
                "id": f"{module_id}_{question_type}",
                "text": question.get("question_text", "") if question else "",
                "type": "multiple_choice"
            },
            "hint": {
                "text": hint.get("hint_text", "") if hint else ""
            },
            "difficulty": difficulty
        }

        return response

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Error fetching module content: {str(e)}")


# ============================================================
# SUBMIT ANSWER AND GET ADAPTIVE DECISION
# ============================================================

@app.post("/api/learning-modules/{module_id}/answer")
def submit_module_answer(module_id: str, request: AnswerRequest):
    """
    Submit an answer for a module question.
    Returns: correctness, mastery_score, and next_difficulty recommendation.
    """
    try:
        # Find the question in content_versions
        question_content = content_versions_collection.find_one({
            "subtopic": module_id,
            "content_type": {"$in": ["easy_question", "medium_question"]}
        })

        if not question_content:
            raise HTTPException(status_code=404, detail="Question not found")

        # Normalize answers for comparison
        correct_answer = str(question_content.get("correct_answer", "")).strip().lower()
        student_answer = str(request.answer).strip().lower()

        is_correct = student_answer == correct_answer

        # Update mastery
        mastery = mastery_state_collection.find_one({
            "student_id": request.student_id,
            "subtopic_id": module_id
        })

        if mastery is None:
            mastery_score = 10 if is_correct else 0
            mastery_state_collection.insert_one({
                "student_id": request.student_id,
                "subtopic_id": module_id,
                "mastery_score": mastery_score,
                "attempts": 1,
                "correct_attempts": 1 if is_correct else 0
            })
        else:
            mastery_score = mastery.get("mastery_score", 0)
            mastery_score += 10 if is_correct else -5
            mastery_score = max(0, min(100, mastery_score))

            mastery_state_collection.update_one(
                {
                    "student_id": request.student_id,
                    "subtopic_id": module_id
                },
                {
                    "$set": {
                        "mastery_score": mastery_score
                    },
                    "$inc": {
                        "attempts": 1,
                        "correct_attempts": 1 if is_correct else 0
                    }
                }
            )

        # Decide next difficulty based on mastery
        if mastery_score >= 70:
            next_difficulty = "hard"
            recommendation = "You're doing great! Try a harder question."
        elif mastery_score >= 50:
            next_difficulty = "medium"
            recommendation = "Good progress! Let's try a medium question."
        else:
            next_difficulty = "easy"
            recommendation = "Let's stick with easy questions to build confidence."

        return {
            "correct": is_correct,
            "mastery_score": mastery_score,
            "next_difficulty": next_difficulty,
            "recommendation": recommendation,
            "correct_answer": question_content.get("correct_answer", "")
        }

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Error submitting answer: {str(e)}")

