from fastapi.middleware.cors import CORSMiddleware

from app.database import (
    content_versions_collection,
    mastery_state_collection,
)
from app.schemas import AnswerRequest

app = FastAPI(title="Adaptive Learning API", version="2.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

SUBTOPICS = [
    "Hosts and access networks",
    "Physical media",
    "Packet switching",
    "Circuit switching",
    "Internet structure",
]


# ── helpers ────────────────────────────────────────────────────────────────────

def _get_mastery(student_id: str, subtopic: str) -> int:
    rec = mastery_state_collection.find_one(
        {"student_id": student_id, "subtopic_id": subtopic}
    )
    return rec["mastery_score"] if rec else 0


def _difficulty_for_score(score: int) -> str:
    if score >= 70:
        return "medium"   # hard content not generated yet, cap at medium
    return "easy"


# ── health ─────────────────────────────────────────────────────────────────────

@app.get("/health")
def health():
    try:
        from app.database import client
        client.admin.command("ping")
        return {"status": "healthy", "mongodb": "connected"}
    except Exception as e:
        return {"status": "unhealthy", "error": str(e)}


# ── list modules ───────────────────────────────────────────────────────────────

@app.get("/api/learning-modules")
def get_learning_modules():
    subtopics = content_versions_collection.distinct("subtopic")
    if not subtopics:
        # Fall back to known list so frontend always gets something
        subtopics = SUBTOPICS
    modules = [
        {
            "id": s,
            "title": s,
            "category": "Academic",
            "description": f"Learn about {s}",
            "estimatedTime": 15,
        }
        for s in subtopics
    ]
    return {"data": modules}


