def get_session(student_id: str, module_id: str):
    score = _get_mastery(student_id, module_id)
    difficulty = _difficulty_for_score(score)
    return {
        "student_id": student_id,
        "module_id": module_id,
        "mastery_score": score,
        "difficulty": difficulty,
    }


