@app.get("/api/learning-modules/{module_id:path}")
def get_module_content(module_id: str, difficulty: str = "easy", student_id: str = "anonymous"):
    # Auto-select difficulty from mastery if not forced
    score = _get_mastery(student_id, module_id)
