def submit_answer(module_id: str, request: AnswerRequest):
    # Find the question document (try the difficulty-specific one first)
    question = content_versions_collection.find_one(
        {"subtopic": module_id, "content_type": {"$in": ["easy_question", "medium_question"]}}
    )
    if not question:
        raise HTTPException(404, "Question not found")

    correct_answer = question.get("correct_answer", "").strip().lower()
    student_answer = (request.answer or "").strip().lower()
    is_correct = student_answer == correct_answer

    # Update mastery
    existing = mastery_state_collection.find_one(
        {"student_id": request.student_id, "subtopic_id": module_id}
    )
    if existing:
        score = existing.get("mastery_score", 0)
        score = max(0, min(100, score + (10 if is_correct else -5)))
        mastery_state_collection.update_one(
            {"student_id": request.student_id, "subtopic_id": module_id},
            {"$set": {"mastery_score": score}, "$inc": {"attempts": 1, "correct_count": 1 if is_correct else 0}},
        )
    else:
        score = 10 if is_correct else 0
        mastery_state_collection.insert_one({
            "student_id": request.student_id,
            "subtopic_id": module_id,
            "mastery_score": score,
            "attempts": 1,
            "correct_count": 1 if is_correct else 0,
        })

    next_difficulty = _difficulty_for_score(score)
    if score >= 70:
        recommendation = "🔥 Excellent! You're mastering this topic."
    elif score >= 50:
        recommendation = "👍 Good progress! Keep going."
    elif is_correct:
        recommendation = "✅ Correct! Let's keep building."
    else:
        recommendation = "💡 Not quite — review the lesson and try again."

    return {
        "correct": is_correct,
        "mastery_score": score,
        "next_difficulty": next_difficulty,
        "recommendation": recommendation,
        "correct_answer": question.get("correct_answer", ""),
        "answer_explanation": question.get("explanation", ""),
    }


# ── mastery summary (all subtopics for a student) ─────────────────────────────

@app.get("/api/mastery/{student_id}")
def get_mastery(student_id: str):
    records = list(
        mastery_state_collection.find({"student_id": student_id}, {"_id": 0})
    )
    return {"student_id": student_id, "records": records}

