"""
Rule-based adaptive engine.

Input:  mastery_score, consecutive_wrong, attempt_number, hint_used
Output: action dict describing what to show next
"""

def decide(mastery_score: int, consecutive_wrong: int, attempt_number: int) -> dict:
    """
    Returns:
        action: "next_subtopic" | "harder" | "same" | "reteach" |
                "example" | "prerequisite" | "escalate"
        content_type: which content piece to fetch
        question_difficulty: "easy" | "medium" | "hard"
        message: short UI message
    """

    # ── escalation ────────────────────────────────────────────────────────────
    if consecutive_wrong >= 5:
        return {
            "action": "escalate",
            "content_type": "prerequisite",
            "question_difficulty": "easy",
            "message": "Great effort! Your teacher will help you with this one 🙌",
        }

    # ── prerequisite recap (4th wrong) ────────────────────────────────────────
    if consecutive_wrong == 4:
        return {
            "action": "prerequisite",
            "content_type": "prerequisite",
            "question_difficulty": "easy",
            "message": "Let's go back to the basics first 📖",
        }

    # ── worked example (3rd wrong) ────────────────────────────────────────────
    if consecutive_wrong == 3:
        return {
            "action": "example",
            "content_type": "example",
            "question_difficulty": "easy",
            "message": "Let me show you an example 💡",
        }

    # ── re-teach simpler (2nd wrong) ──────────────────────────────────────────
    if consecutive_wrong == 2:
        return {
            "action": "reteach",
            "content_type": "simple_explanation",
            "question_difficulty": "easy",
            "message": "Let's try a simpler explanation 🔄",
        }

    # ── hint shown (1st wrong — handled in endpoint, just retry same) ─────────
    if consecutive_wrong == 1:
        return {
            "action": "hint",
            "content_type": "main_explanation",
            "question_difficulty": "easy",
            "message": "Not quite — here's a hint 💬",
        }

    # ── correct — decide difficulty for next question ─────────────────────────
    if mastery_score >= 80:
        return {
            "action": "next_subtopic",
            "content_type": "main_explanation",
            "question_difficulty": "easy",
            "message": "🎉 You understood this! Moving on.",
        }

    if mastery_score >= 60:
        return {
            "action": "harder",
            "content_type": "main_explanation",
            "question_difficulty": "medium",
            "message": "Great job! Let's try something a bit harder 🚀",
        }

    return {
        "action": "same",
        "content_type": "main_explanation",
        "question_difficulty": "easy",
        "message": "Correct! Keep going 👍",
    }


def question_difficulty_for_mastery(mastery: int) -> str:
    if mastery >= 70:
        return "hard"
    if mastery >= 40:
        return "medium"
    return "easy"

