"""
LLM content generator using Groq.
Generates all 7 content types for a subtopic.
Each piece is short, simple, suitable for low-reading-ability students.
"""

import os, json, re
from groq import Groq
from dotenv import load_dotenv

load_dotenv()

GROQ_API_KEY = os.getenv("GROQ_API_KEY", "")
GROQ_MODEL   = os.getenv("GROQ_MODEL", "llama3-8b-8192")

client = Groq(api_key=GROQ_API_KEY)


SYSTEM_PROMPT = """You are a content creator for an adaptive learning platform for students with intellectual disabilities.
Rules:
- Use VERY simple English. Max 2 sentences per explanation.
- Questions must have exactly 4 options (A, B, C, D).
- One correct answer per question.
- Options should be short (2-5 words each).
- Always return valid JSON only, no markdown.
"""


def _call(prompt: str) -> dict:
    resp = client.chat.completions.create(
        model=GROQ_MODEL,
        messages=[
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user",   "content": prompt},
        ],
        temperature=0.4,
        response_format={"type": "json_object"},
    )
    raw = resp.choices[0].message.content
    return json.loads(raw)


def generate_all(topic: str, subtopic: str) -> dict:
    """
    Generate all content types for a subtopic.
    Returns a dict keyed by content_type.
    """
    prompt = f"""
Generate all learning content for the subtopic "{subtopic}" which is part of the topic "{topic}".

Return a JSON object with these exact keys:

{{
  "main_explanation": {{
    "text": "2 simple sentences explaining {subtopic}. Use simple words.",
    "emoji": "a single relevant emoji"
  }},
  "simple_explanation": {{
    "text": "1 very simple sentence. Even simpler than main_explanation.",
    "emoji": "a single relevant emoji"
  }},
  "example": {{
    "text": "1 sentence: It is like [familiar analogy]. Make it very relatable.",
    "emoji": "a single relevant emoji"
  }},
  "prerequisite": {{
    "text": "1 sentence explaining what basic concept the student needs to know first.",
    "emoji": "a single relevant emoji"
  }},
  "hint": {{
    "text": "1 sentence hint that nudges toward the answer without giving it away.",
    "emoji": "💡"
  }},
  "question": {{
    "text": "A clear simple question about {subtopic}.",
    "options": ["option A text", "option B text", "option C text", "option D text"],
    "correct": 0,
    "explanation": "1 sentence why this is correct."
  }},
  "easy_question": {{
    "text": "A simpler/easier question about {subtopic}.",
    "options": ["option A text", "option B text", "option C text", "option D text"],
    "correct": 0,
    "explanation": "1 sentence why this is correct."
  }}
}}

Important:
- "correct" is the 0-based index of the correct option (0, 1, 2, or 3)
- Keep ALL text very short and simple
- The topic context is: {topic}
"""
    return _call(prompt)


def generate_fallback(topic: str, subtopic: str) -> dict:
    """Fallback mock content when Groq is unavailable."""
    return {
        "main_explanation": {
            "text": f"{subtopic} is an important part of {topic}. It helps us understand how things work.",
            "emoji": "📚"
        },
        "simple_explanation": {
            "text": f"{subtopic} is a basic idea in {topic}.",
            "emoji": "💡"
        },
        "example": {
            "text": f"Think of {subtopic} like sending a letter — it goes step by step.",
            "emoji": "✉️"
        },
        "prerequisite": {
            "text": f"Before learning {subtopic}, make sure you understand what {topic} is about.",
            "emoji": "🔑"
        },
        "hint": {
            "text": f"Think about what {subtopic} does and how it connects to {topic}.",
            "emoji": "💡"
        },
        "question": {
            "text": f"What is {subtopic}?",
            "options": [
                f"A key part of {topic}",
                "Something unrelated",
                "A type of food",
                "A weather event"
            ],
            "correct": 0,
            "explanation": f"{subtopic} is indeed a key part of {topic}."
        },
        "easy_question": {
            "text": f"Is {subtopic} part of {topic}?",
            "options": ["Yes", "No", "Maybe", "I don't know"],
            "correct": 0,
            "explanation": f"Yes, {subtopic} is part of {topic}."
        }
    }

