            generated = generate_all(topic, sub["name"])
        except Exception:
            traceback.print_exc()
            generated = generate_fallback(topic, sub["name"])

        # store each content type as a separate doc
        for ctype, cdata in generated.items():
            # upsert so re-generation replaces old content
            content_col.update_one(
                {"subtopic_id": sub_id, "type": ctype},
                {"$set": {
                    "subtopic_id": sub_id,
                    "unit_id": unit_id,
                    "topic": topic,
                    "subtopic_name": sub["name"],
                    "type": ctype,
                    "data": cdata,
                    "approved": False,
                    "updated_at": now(),
                }},
                upsert=True,
            )

        subtopics_col.update_one(
            {"_id": ObjectId(sub_id)},
            {"$set": {"generation_status": "done"}}
        )

    units_col.update_one(
        {"_id": ObjectId(unit_id)},
        {"$set": {"status": "ready"}}
    )


# ══════════════════════════════════════════════════════════════════════════════
# TEACHER — GET UNIT STATUS + CONTENT FOR REVIEW
# ══════════════════════════════════════════════════════════════════════════════

@app.get("/api/teacher/units/{unit_id}/status")
def unit_status(unit_id: str):
    unit = units_col.find_one({"_id": ObjectId(unit_id)})
    if not unit:
        raise HTTPException(404, "Unit not found")
    return {"status": unit.get("status", "unknown"), "topic": unit["topic"]}


@app.get("/api/teacher/units/{unit_id}/review")
def review_content(unit_id: str):
    """Returns all content grouped by subtopic for teacher review."""
    subs = list(subtopics_col.find({"unit_id": unit_id}, {"_id": 1, "name": 1, "order": 1, "content_approved": 1}))
    result = []
    for sub in subs:
        sub_id = str(sub["_id"])
        pieces = list(content_col.find({"subtopic_id": sub_id}))
        result.append({
            "subtopic_id": sub_id,
            "name": sub["name"],
            "order": sub["order"],
            "content_approved": sub.get("content_approved", False),
            "content": [
                {
                    "type": p["type"],
                    "data": p["data"],
                    "approved": p.get("approved", False),
                }
                for p in pieces
            ]
        })
    result.sort(key=lambda x: x["order"])
    return {"unit_id": unit_id, "subtopics": result}


@app.post("/api/teacher/approve")
def approve_subtopic(req: ApproveContentRequest):
    """Teacher approves all content for a subtopic — makes it live for students."""
    content_col.update_many(
        {"subtopic_id": req.subtopic_id},
        {"$set": {"approved": True}}
    )
    subtopics_col.update_one(
        {"_id": ObjectId(req.subtopic_id)},
        {"$set": {"content_approved": True}}
    )
    return {"message": "Subtopic approved and live for students."}


@app.get("/api/teacher/units")
def list_units(teacher_id: str):
    units = list(units_col.find({"teacher_id": teacher_id}))
    return {"units": [oid(u) for u in units]}


# ══════════════════════════════════════════════════════════════════════════════
# TEACHER — ESCALATION DASHBOARD
# ══════════════════════════════════════════════════════════════════════════════

@app.get("/api/teacher/escalations")
def get_escalations(teacher_id: str = ""):
    query = {"resolved": False}
    escs = list(escalations_col.find(query).sort("created_at", -1))
    return {"escalations": [oid(e) for e in escs]}


@app.post("/api/teacher/escalations/resolve")
def resolve_escalation(req: ResolveEscalationRequest):
    esc = escalations_col.find_one({"_id": ObjectId(req.escalation_id)})
    if not esc:
        raise HTTPException(404, "Escalation not found")

    escalations_col.update_one(
        {"_id": ObjectId(req.escalation_id)},
        {"$set": {"resolved": True, "teacher_note": req.teacher_note, "resolved_at": now()}}
    )

    # unblock student for this subtopic by resetting consecutive_wrong
    mastery_col.update_one(
        {"student_id": esc["student_id"], "subtopic_id": esc["subtopic_id"]},
        {"$set": {"consecutive_wrong": 0, "escalated": False, "status": "skipped"}}
    )
    return {"message": "Student unblocked. They will skip to the next subtopic."}


# ══════════════════════════════════════════════════════════════════════════════
# STUDENT — GET AVAILABLE TOPICS
# ══════════════════════════════════════════════════════════════════════════════

@app.get("/api/student/topics")
def get_topics():
    """All approved units visible to students."""
    units = list(units_col.find({"status": "ready"}))
    result = []
    for u in units:
        unit_id = str(u["_id"])
        sub_count = subtopics_col.count_documents({"unit_id": unit_id, "content_approved": True})
        result.append({
            "unit_id": unit_id,
            "topic": u["topic"],
            "approved_subtopics": sub_count,
        })
    return {"topics": result}


# ══════════════════════════════════════════════════════════════════════════════
# STUDENT — GET NEXT ACTIVITY
# ══════════════════════════════════════════════════════════════════════════════

@app.get("/api/student/next-activity")
def next_activity(student_id: str, unit_id: str):
    """
    Returns what the student should see next:
    content to read + question to answer.
    Handles escalation skip logic.
    """
    # get all approved subtopics in order
    subs = list(subtopics_col.find(
        {"unit_id": unit_id, "content_approved": True},
    ).sort("order", 1))

    if not subs:
        raise HTTPException(404, "No approved content yet. Teacher needs to approve content first.")

    # find first subtopic not yet mastered (mastery < 80) and not skipped
    current_sub = None
    for sub in subs:
        sub_id = str(sub["_id"])
        mastery = mastery_col.find_one({"student_id": student_id, "subtopic_id": sub_id})
        if mastery is None:
            # never started — this is next
            current_sub = sub
            break
        status = mastery.get("status", "active")
        if status in ("mastered", "skipped"):
            continue
        if mastery.get("escalated", False):
            # check if resolved
            esc = escalations_col.find_one({
                "student_id": student_id,
                "subtopic_id": sub_id,
                "resolved": False
            })
            if esc:
                # still waiting — skip if not prerequisite
                continue
        current_sub = sub
        break

    # all subtopics done
    if current_sub is None:
        return _post_test_summary(student_id, unit_id, subs)

    sub_id = str(current_sub["_id"])
    mastery_doc = mastery_col.find_one({"student_id": student_id, "subtopic_id": sub_id})
    mastery_score     = mastery_doc["mastery_score"]     if mastery_doc else 0
    consecutive_wrong = mastery_doc["consecutive_wrong"] if mastery_doc else 0
    attempt_number    = mastery_doc["attempt_number"]    if mastery_doc else 0

    # decide what to show
    decision = decide(mastery_score, consecutive_wrong, attempt_number)
    content_type = decision["content_type"]
    q_difficulty = decision["question_difficulty"]

    # fetch content piece
    content_piece = content_col.find_one({"subtopic_id": sub_id, "type": content_type, "approved": True})
    if not content_piece:
        content_piece = content_col.find_one({"subtopic_id": sub_id, "type": "main_explanation", "approved": True})
    if not content_piece:
        raise HTTPException(404, f"No approved content for subtopic '{current_sub['name']}'")

    # fetch appropriate question
    q_type = "easy_question" if q_difficulty == "easy" else "question"
    question_piece = content_col.find_one({"subtopic_id": sub_id, "type": q_type, "approved": True})
    if not question_piece:
        question_piece = content_col.find_one({"subtopic_id": sub_id, "type": "question", "approved": True})

    hint_piece = content_col.find_one({"subtopic_id": sub_id, "type": "hint", "approved": True})

    # baseline flag: first time visiting this subtopic
    is_baseline = (mastery_doc is None)
    if is_baseline:
        mastery_col.insert_one({
            "student_id": student_id,
            "subtopic_id": sub_id,
            "unit_id": unit_id,
            "mastery_score": 0,
            "consecutive_wrong": 0,
            "attempt_number": 0,
            "hint_used_count": 0,
            "status": "active",
            "escalated": False,
            "created_at": now(),
        })

    return {
        "subtopic_id": sub_id,
        "subtopic_name": current_sub["name"],
        "topic": current_sub["topic"],
        "is_baseline": is_baseline,
        "mastery_score": mastery_score,
        "consecutive_wrong": consecutive_wrong,
        "action": decision["action"],
        "message": decision["message"],
        "content": content_piece["data"] if content_piece else {},
        "content_type": content_type,
        "question": question_piece["data"] if question_piece else None,
        "question_type": q_type,
        "hint": hint_piece["data"]["text"] if hint_piece else "",
        "show_hint": consecutive_wrong >= 1,
    }


def _post_test_summary(student_id: str, unit_id: str, subs: list):
    """Build post-test / completion summary."""
    records = []
    total_score = 0
    for sub in subs:
        sub_id = str(sub["_id"])
        m = mastery_col.find_one({"student_id": student_id, "subtopic_id": sub_id})
        score = m["mastery_score"] if m else 0
        total_score += score
        records.append({
            "subtopic": sub["name"],
            "mastery_score": score,
            "status": m.get("status", "unknown") if m else "not_started",
        })
    avg = total_score // len(subs) if subs else 0
    return {
        "completed": True,
        "avg_mastery": avg,
        "subtopics": records,
        "message": "🎉 You completed all subtopics!" if avg >= 60 else "Keep practising — you're getting better!",
    }


# ══════════════════════════════════════════════════════════════════════════════
# STUDENT — SUBMIT ANSWER
# ══════════════════════════════════════════════════════════════════════════════

@app.post("/api/student/submit-answer")
def submit_answer(req: SubmitAnswerRequest):
    sub = subtopics_col.find_one({"_id": ObjectId(req.subtopic_id)})
    if not sub:
        raise HTTPException(404, "Subtopic not found")

    sub_id = req.subtopic_id

    # find the question that was asked (same logic as next-activity)
    mastery_doc = mastery_col.find_one({"student_id": req.student_id, "subtopic_id": sub_id})
    mastery_score     = mastery_doc["mastery_score"]     if mastery_doc else 0
    consecutive_wrong = mastery_doc["consecutive_wrong"] if mastery_doc else 0
    attempt_number    = mastery_doc["attempt_number"]    if mastery_doc else 0

    q_difficulty = question_difficulty_for_mastery(mastery_score)
    q_type = "easy_question" if q_difficulty == "easy" or consecutive_wrong > 0 else "question"
    question_piece = content_col.find_one({"subtopic_id": sub_id, "type": q_type, "approved": True})
    if not question_piece:
        question_piece = content_col.find_one({"subtopic_id": sub_id, "type": "question", "approved": True})
    if not question_piece:
        raise HTTPException(404, "Question not found")

    q_data   = question_piece["data"]
    correct  = (req.selected_option == q_data["correct"])

    # score delta
    if correct:
        delta = 5 if req.hint_used else 10
    else:
        delta = -5

    new_score = max(0, min(100, mastery_score + delta))
    new_wrong = 0 if correct else consecutive_wrong + 1
    new_attempt = attempt_number + 1

    # record attempt
    attempts_col.insert_one({
        "student_id": req.student_id,
        "subtopic_id": sub_id,
        "selected_option": req.selected_option,
        "correct": correct,
        "hint_used": req.hint_used,
        "mastery_before": mastery_score,
        "mastery_after": new_score,
        "timestamp": now(),
    })

    # check escalation
    escalated = False
    if new_wrong >= 5:
        escalated = True
        # create escalation alert
        existing = escalations_col.find_one({
            "student_id": req.student_id,
            "subtopic_id": sub_id,
            "resolved": False
        })
        if not existing:
            escalations_col.insert_one({
                "student_id": req.student_id,
                "subtopic_id": sub_id,
                "unit_id": sub.get("unit_id", ""),
                "subtopic_name": sub["name"],
                "mastery_score": new_score,
                "attempt_count": new_attempt,
                "resolved": False,
                "created_at": now(),
            })

    # determine new status
    new_status = "active"
    if new_score >= 80:
        new_status = "mastered"
    elif escalated:
        new_status = "escalated"

    # update mastery
    mastery_col.update_one(
        {"student_id": req.student_id, "subtopic_id": sub_id},
        {"$set": {
            "mastery_score": new_score,
            "consecutive_wrong": new_wrong,
            "attempt_number": new_attempt,
            "hint_used_count": (mastery_doc.get("hint_used_count", 0) if mastery_doc else 0) + (1 if req.hint_used else 0),
            "status": new_status,
            "escalated": escalated,
            "last_updated": now(),
        }},
        upsert=True,
    )

    # build next_action for frontend
    decision = decide(new_score, new_wrong, new_attempt)

    return {
        "correct": correct,
        "correct_option": q_data["correct"],
        "explanation": q_data.get("explanation", ""),
        "mastery_score": new_score,
        "mastery_delta": delta,
        "consecutive_wrong": new_wrong,
        "status": new_status,
        "escalated": escalated,
        "next_action": decision["action"],
        "next_message": decision["message"],
    }


# ══════════════════════════════════════════════════════════════════════════════
# STUDENT — MASTERY SUMMARY
# ══════════════════════════════════════════════════════════════════════════════

@app.get("/api/student/mastery")
def get_mastery(student_id: str, unit_id: str):
    subs = list(subtopics_col.find({"unit_id": unit_id}).sort("order", 1))
    records = []
    for sub in subs:
        sub_id = str(sub["_id"])
        m = mastery_col.find_one({"student_id": student_id, "subtopic_id": sub_id})
        records.append({
            "subtopic_id": sub_id,
            "name": sub["name"],
            "mastery_score": m["mastery_score"] if m else 0,
            "status": m.get("status", "not_started") if m else "not_started",
            "attempts": m.get("attempt_number", 0) if m else 0,
        })
    return {"student_id": student_id, "unit_id": unit_id, "subtopics": records}

