import { useEffect, useRef, useState } from "react";
import { studentApi } from "../api/adaptiveApi";

const P = "Poppins, sans-serif";

// ── TTS helper ─────────────────────────────────────────────────────────────

function speak(text: string) {
  if (!("speechSynthesis" in window)) return;
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.rate = 0.85;
  u.pitch = 1.05;
  window.speechSynthesis.speak(u);
}

// ── shared small components ────────────────────────────────────────────────

function SpeakBtn({ text }: { text: string }) {
  return (
    <button onClick={() => speak(text)} title="Listen" style={{
      background: "rgba(34,211,238,.1)", border: "1px solid rgba(34,211,238,.2)",
      borderRadius: 8, padding: "6px 12px", cursor: "pointer",
      color: "#67e8f9", fontFamily: P, fontSize: 13, fontWeight: 700,
    }}>
      🔊 Listen
    </button>
  );
}

function MasteryBar({ score }: { score: number }) {
  const color = score >= 80 ? "#22c55e" : score >= 50 ? "#f59e0b" : "#7c3aed";
  return (
    <div style={{ background: "rgba(255,255,255,.08)", borderRadius: 99, height: 10, overflow: "hidden" }}>
      <div style={{
        width: `${score}%`, height: "100%", background: color,
        borderRadius: 99, transition: "width 0.6s ease",
      }} />
    </div>
  );
}

// ── LOGIN screen ────────────────────────────────────────────────────────────

function LoginScreen({ onLogin }: { onLogin: (name: string) => void }) {
  const [name, setName] = useState("");
  return (
    <div style={{
      minHeight: "100vh", background: "#070b24", display: "flex",
      alignItems: "center", justifyContent: "center", padding: 24,
    }}>
      <div style={{
        background: "#111827", borderRadius: 24, padding: 48,
        maxWidth: 400, width: "100%", textAlign: "center",
        border: "1px solid rgba(124,58,237,.2)",
      }}>
        <div style={{ fontSize: 64 }}>🌟</div>
        <h1 style={{ fontFamily: P, fontWeight: 900, color: "#f1f5f9", fontSize: 28, margin: "16px 0 8px" }}>
          Welcome!
        </h1>
        <p style={{ fontFamily: P, color: "#64748b", fontSize: 15, margin: "0 0 32px" }}>
          What is your name?
        </p>
        <input
          value={name}
          onChange={e => setName(e.target.value)}
          onKeyDown={e => e.key === "Enter" && name.trim() && onLogin(name.trim())}
          placeholder="Type your name..."
          autoFocus
          style={{
            width: "100%", padding: "14px 16px", borderRadius: 12, boxSizing: "border-box",
            background: "rgba(255,255,255,.06)", border: "2px solid rgba(124,58,237,.3)",
            color: "#fff", fontFamily: P, fontSize: 18, outline: "none", textAlign: "center",
          }}
        />
        <button
          onClick={() => name.trim() && onLogin(name.trim())}
          disabled={!name.trim()}
          style={{
            marginTop: 16, width: "100%", padding: "16px 0", borderRadius: 12, border: "none",
            background: name.trim() ? "linear-gradient(135deg,#7c3aed,#4f46e5)" : "#1e293b",
            color: "#fff", fontFamily: P, fontWeight: 800, fontSize: 18,
            cursor: name.trim() ? "pointer" : "default",
          }}
        >
          Let's Learn! 🚀
        </button>
      </div>
    </div>
  );
}

// ── TOPIC SELECT screen ────────────────────────────────────────────────────

function TopicSelect({ studentId, onSelect }: { studentId: string; onSelect: (unitId: string, topic: string) => void }) {
  const [topics, setTopics] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    studentApi.getTopics()
      .then(d => setTopics(d.topics))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  if (loading) return (
    <div style={{ minHeight: "100vh", background: "#070b24", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <p style={{ fontFamily: P, color: "#64748b", fontSize: 18 }}>Loading topics…</p>
    </div>
  );

  return (
    <div style={{ minHeight: "100vh", background: "#070b24", padding: "40px 24px" }}>
      <div style={{ maxWidth: 600, margin: "0 auto" }}>
        <h1 style={{ fontFamily: P, fontWeight: 900, color: "#f1f5f9", fontSize: 30, textAlign: "center" }}>
          Hi {studentId}! 👋
        </h1>
        <p style={{ fontFamily: P, color: "#64748b", textAlign: "center", marginBottom: 32, fontSize: 16 }}>
          Choose what you want to learn today
        </p>

        {topics.length === 0 ? (
          <div style={{
            background: "#111827", borderRadius: 20, padding: 40, textAlign: "center",
            border: "1px solid rgba(255,255,255,.06)",
          }}>
            <div style={{ fontSize: 48 }}>⏳</div>
            <p style={{ fontFamily: P, color: "#94a3b8", marginTop: 12 }}>
              Your teacher hasn't published any content yet.
            </p>
            <p style={{ fontFamily: P, color: "#475569", fontSize: 13 }}>Check back later!</p>
          </div>
        ) : (
          <div style={{ display: "grid", gap: 16 }}>
            {topics.map((t: any) => (
              <button
                key={t.unit_id}
                onClick={() => onSelect(t.unit_id, t.topic)}
                style={{
                  background: "#111827", border: "2px solid rgba(124,58,237,.2)",
                  borderRadius: 20, padding: "24px 28px", cursor: "pointer",
                  textAlign: "left", width: "100%",
                  transition: "border-color 0.2s",
                }}
                onMouseEnter={e => (e.currentTarget.style.borderColor = "rgba(124,58,237,.6)")}
                onMouseLeave={e => (e.currentTarget.style.borderColor = "rgba(124,58,237,.2)")}
              >
                <div style={{ fontSize: 36, marginBottom: 8 }}>📘</div>
                <div style={{ fontFamily: P, fontWeight: 800, color: "#f1f5f9", fontSize: 22 }}>
                  {t.topic}
                </div>
                <div style={{ fontFamily: P, color: "#64748b", fontSize: 14, marginTop: 4 }}>
                  {t.approved_subtopics} subtopics ready
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ── LEARNING LOOP screen ────────────────────────────────────────────────────

type LearningPhase = "loading" | "content" | "question" | "feedback" | "escalated" | "completed";

function LearningLoop({
  studentId, unitId, topic,
  onDone,
}: {
  studentId: string; unitId: string; topic: string;
  onDone: () => void;
}) {
  const [phase, setPhase] = useState<LearningPhase>("loading");
  const [activity, setActivity] = useState<any>(null);
  const [selected, setSelected] = useState<number | null>(null);
  const [result, setResult] = useState<any>(null);
  const [hintShown, setHintShown] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const hasAutoRead = useRef(false);

  async function loadNext() {
    setPhase("loading");
    setSelected(null);
    setResult(null);
    setHintShown(false);
    hasAutoRead.current = false;
    try {
      const data = await studentApi.getNextActivity(studentId, unitId);
      if (data.completed) {
        setActivity(data);
        setPhase("completed");
        return;
      }
      setActivity(data);
      setPhase("content");
    } catch (e: any) {
      alert("Could not load activity. Is the backend running?\n" + (e?.message || ""));
    }
  }

  useEffect(() => { loadNext(); }, []);

  // auto-read content when phase changes to "content" or "question"
  useEffect(() => {
    if (!activity || hasAutoRead.current) return;
    if (phase === "content" && activity.content?.text) {
      hasAutoRead.current = true;
      const emoji = activity.content.emoji || "";
      speak(`${activity.message || ""}. ${activity.content.text}`);
    }
    if (phase === "question" && activity.question?.text) {
      hasAutoRead.current = true;
      speak(activity.question.text);
    }
  }, [phase, activity]);

  async function handleSubmit() {
    if (selected === null || !activity) return;
    setSubmitting(true);
    try {
      const res = await studentApi.submitAnswer({
        student_id: studentId,
        subtopic_id: activity.subtopic_id,
        selected_option: selected,
        hint_used: hintShown,
      });
      setResult(res);
      setActivity((prev: any) => ({ ...prev, mastery_score: res.mastery_score }));

      if (res.escalated) {
        speak("Don't worry! Your teacher will help you with this.");
        setPhase("escalated");
      } else {
        speak(res.correct ? "Correct! Great job!" : "Not quite. Let's keep trying.");
        setPhase("feedback");
      }
    } catch (e: any) {
      alert("Could not submit. Is the backend running?");
    } finally {
      setSubmitting(false);
    }
  }

  function handleNext() {
    if (!result) return;
    if (result.status === "mastered") {
      speak("Amazing! You mastered this topic. Let's move on!");
    }
    loadNext();
  }

  if (phase === "loading") return (
    <Screen>
      <div style={{ textAlign: "center", paddingTop: 80 }}>
        <div style={{ fontSize: 56 }}>⏳</div>
        <p style={{ fontFamily: P, color: "#64748b", fontSize: 18, marginTop: 12 }}>Loading…</p>
      </div>
    </Screen>
  );

  if (phase === "completed") return (
    <Screen>
      <div style={{ textAlign: "center", maxWidth: 500, margin: "0 auto", paddingTop: 40 }}>
        <div style={{ fontSize: 72 }}>🎉</div>
        <h2 style={{ fontFamily: P, fontWeight: 900, color: "#4ade80", fontSize: 30, margin: "16px 0 8px" }}>
          You did it!
        </h2>
        <p style={{ fontFamily: P, color: "#94a3b8", fontSize: 16 }}>
          {activity?.message || "You completed all subtopics!"}
        </p>
        {activity?.subtopics && (
          <div style={{ marginTop: 24, textAlign: "left" }}>
            {activity.subtopics.map((s: any) => (
              <div key={s.subtopic} style={{
                display: "flex", justifyContent: "space-between", alignItems: "center",
                padding: "10px 14px", background: "rgba(255,255,255,.04)", borderRadius: 10, marginBottom: 8,
              }}>
                <span style={{ fontFamily: P, color: "#f1f5f9", fontSize: 15 }}>{s.subtopic}</span>
                <span style={{
                  fontFamily: P, fontWeight: 700, fontSize: 14,
                  color: s.mastery_score >= 80 ? "#4ade80" : s.mastery_score >= 50 ? "#fbbf24" : "#f87171"
                }}>
                  {s.mastery_score}/100 {s.status === "skipped" ? "(skipped)" : ""}
                </span>
              </div>
            ))}
          </div>
        )}
        <BigBtn onClick={onDone} style={{ marginTop: 24 }}>← Back to Topics</BigBtn>
      </div>
    </Screen>
  );

  if (phase === "escalated") return (
    <Screen>
      <div style={{ textAlign: "center", maxWidth: 440, margin: "0 auto", paddingTop: 60 }}>
        <div style={{ fontSize: 72 }}>🙌</div>
        <h2 style={{ fontFamily: P, fontWeight: 900, color: "#fbbf24", fontSize: 26, margin: "16px 0 8px" }}>
          Great effort!
        </h2>
        <p style={{ fontFamily: P, color: "#94a3b8", fontSize: 16, lineHeight: 1.7 }}>
          Your teacher has been notified and will help you with this topic.
          <br />
          Moving on to the next one!
        </p>
        <div style={{ marginTop: 32, padding: 20, background: "rgba(245,158,11,.08)", borderRadius: 16, border: "1px solid rgba(245,158,11,.2)" }}>
          <p style={{ fontFamily: P, color: "#fbbf24", margin: 0, fontSize: 15 }}>
            📣 Teacher has been alerted about your difficulty with <strong>{activity?.subtopic_name}</strong>
          </p>
        </div>
        <BigBtn onClick={loadNext} style={{ marginTop: 24 }}>Continue to next topic →</BigBtn>
      </div>
    </Screen>
  );

  const content = activity?.content;
  const question = activity?.question;
  const mastery = activity?.mastery_score ?? 0;

  return (
    <Screen>
      {/* top bar */}
      <div style={{ marginBottom: 24 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
          <span style={{ fontFamily: P, fontWeight: 700, color: "#f1f5f9", fontSize: 18 }}>
            {activity?.subtopic_name}
          </span>
          <span style={{ fontFamily: P, color: "#7c3aed", fontWeight: 700, fontSize: 15 }}>
            {mastery}/100
          </span>
        </div>
        <MasteryBar score={mastery} />
        {activity?.is_baseline && (
          <p style={{ fontFamily: P, color: "#f59e0b", fontSize: 13, marginTop: 6 }}>
            📋 Baseline — let's see what you already know!
          </p>
        )}
      </div>

      {/* message banner */}
      {activity?.message && (
        <div style={{
          padding: "10px 16px", borderRadius: 10, marginBottom: 20,
          background: "rgba(124,58,237,.12)", border: "1px solid rgba(124,58,237,.2)",
          fontFamily: P, fontSize: 14, color: "#c4b5fd",
        }}>
          {activity.message}
        </div>
      )}

      {/* CONTENT phase */}
      {phase === "content" && content && (
        <div>
          <div style={{
            background: "#111827", borderRadius: 20, padding: 28,
            border: "1px solid rgba(255,255,255,.06)", marginBottom: 24,
          }}>
            <div style={{ fontSize: 48, textAlign: "center", marginBottom: 12 }}>
              {content.emoji || "📖"}
            </div>
            <p style={{
              fontFamily: P, fontSize: 20, fontWeight: 600, color: "#f1f5f9",
              lineHeight: 1.7, textAlign: "center", margin: 0,
            }}>
              {content.text}
            </p>
            <div style={{ textAlign: "center", marginTop: 16 }}>
              <SpeakBtn text={content.text} />
            </div>
          </div>

          <BigBtn onClick={() => { hasAutoRead.current = false; setPhase("question"); }}>
            I understand — answer question →
          </BigBtn>
        </div>
      )}

      {/* QUESTION phase */}
      {phase === "question" && question && (
        <div>
          <div style={{
            background: "#111827", borderRadius: 20, padding: 24,
            border: "1px solid rgba(255,255,255,.06)", marginBottom: 20,
          }}>
            <p style={{ fontFamily: P, fontSize: 19, fontWeight: 700, color: "#f1f5f9", lineHeight: 1.6, margin: "0 0 8px" }}>
              {question.text}
            </p>
            <SpeakBtn text={question.text} />

            {/* hint */}
            {hintShown && activity?.hint && (
              <div style={{
                marginTop: 16, padding: "12px 16px", borderRadius: 12,
                background: "rgba(245,158,11,.08)", border: "1px solid rgba(245,158,11,.2)",
                fontFamily: P, fontSize: 14, color: "#fcd34d",
              }}>
                💡 {activity.hint}
              </div>
            )}
            {!hintShown && activity?.show_hint && activity?.hint && (
              <button onClick={() => { setHintShown(true); speak(activity.hint); }} style={{
                marginTop: 12, background: "none", border: "1px solid rgba(245,158,11,.3)",
                borderRadius: 8, padding: "6px 12px", color: "#f59e0b",
                fontFamily: P, fontSize: 13, cursor: "pointer",
              }}>
                💡 Show hint
              </button>
            )}
          </div>

          {/* options */}
          <div style={{ display: "grid", gap: 12, marginBottom: 20 }}>
            {question.options?.map((opt: string, i: number) => {
              const chosen = selected === i;
              return (
                <button key={i} onClick={() => { setSelected(i); speak(opt); }} style={{
                  padding: "16px 20px", borderRadius: 14, border: `2px solid ${chosen ? "#7c3aed" : "rgba(255,255,255,.08)"}`,
                  background: chosen ? "rgba(124,58,237,.15)" : "rgba(255,255,255,.03)",
                  cursor: "pointer", textAlign: "left", width: "100%",
                  display: "flex", alignItems: "center", gap: 14,
                }}>
                  <span style={{
                    width: 32, height: 32, borderRadius: "50%", flexShrink: 0,
                    background: chosen ? "#7c3aed" : "rgba(255,255,255,.08)",
                    display: "flex", alignItems: "center", justifyContent: "center",
                    fontFamily: P, fontWeight: 800, fontSize: 14,
                    color: chosen ? "#fff" : "#64748b",
                  }}>
                    {["A", "B", "C", "D"][i]}
                  </span>
                  <span style={{ fontFamily: P, fontSize: 17, color: chosen ? "#f1f5f9" : "#94a3b8", fontWeight: chosen ? 700 : 400 }}>
                    {opt}
                  </span>
                </button>
              );
            })}
          </div>

          <BigBtn onClick={handleSubmit} disabled={selected === null || submitting}>
            {submitting ? "Checking…" : "Submit Answer ✓"}
          </BigBtn>
        </div>
      )}

      {/* FEEDBACK phase */}
      {phase === "feedback" && result && (
        <div>
          <div style={{
            borderRadius: 20, padding: 28, textAlign: "center", marginBottom: 24,
            background: result.correct ? "rgba(34,197,94,.08)" : "rgba(239,68,68,.08)",
            border: `2px solid ${result.correct ? "rgba(34,197,94,.25)" : "rgba(239,68,68,.25)"}`,
          }}>
            <div style={{ fontSize: 64 }}>{result.correct ? "✅" : "❌"}</div>
            <h3 style={{
              fontFamily: P, fontWeight: 900, fontSize: 26, margin: "12px 0 8px",
              color: result.correct ? "#4ade80" : "#f87171",
            }}>
              {result.correct ? "Correct!" : "Not quite!"}
            </h3>
            {result.explanation && (
              <p style={{ fontFamily: P, color: "#94a3b8", fontSize: 16, margin: "0 0 16px", lineHeight: 1.6 }}>
                {result.explanation}
              </p>
            )}
            <SpeakBtn text={result.correct ? "Correct! " + (result.explanation || "") : "Not quite. " + (result.explanation || "")} />
          </div>

          {!result.correct && (
            <div style={{
              background: "rgba(255,255,255,.04)", borderRadius: 14, padding: "14px 18px",
              marginBottom: 20, fontFamily: P, fontSize: 15, color: "#4ade80",
            }}>
              ✓ Correct answer: <strong>{activity?.question?.options?.[result.correct_option]}</strong>
            </div>
          )}

          <div style={{ marginBottom: 20 }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6, fontFamily: P, fontSize: 13, color: "#64748b" }}>
              <span>Mastery</span>
              <span style={{ color: result.mastery_delta >= 0 ? "#4ade80" : "#f87171", fontWeight: 700 }}>
                {result.mastery_delta >= 0 ? "+" : ""}{result.mastery_delta} pts → {result.mastery_score}/100
              </span>
            </div>
            <MasteryBar score={result.mastery_score} />
          </div>

          {result.status === "mastered" && (
            <div style={{
              padding: "12px 16px", borderRadius: 12, marginBottom: 16,
              background: "rgba(34,197,94,.1)", border: "1px solid rgba(34,197,94,.2)",
              fontFamily: P, color: "#4ade80", fontWeight: 700, fontSize: 15, textAlign: "center",
            }}>
              🏆 Subtopic mastered! Moving to the next one.
            </div>
          )}

          <BigBtn onClick={handleNext}>
            {result.status === "mastered" ? "Next Subtopic 🚀" : "Continue →"}
          </BigBtn>
        </div>
      )}
    </Screen>
  );
}

// ── layout helpers ──────────────────────────────────────────────────────────

function Screen({ children }: { children: React.ReactNode }) {
  return (
    <div style={{ minHeight: "100vh", background: "#070b24", color: "#fff" }}>
      <div style={{ maxWidth: 560, margin: "0 auto", padding: "32px 20px" }}>
        {children}
      </div>
    </div>
  );
}

function BigBtn({ onClick, children, disabled = false, style = {} }: {
  onClick: () => void; children: React.ReactNode; disabled?: boolean; style?: React.CSSProperties;
}) {
  return (
    <button onClick={onClick} disabled={disabled} style={{
      width: "100%", padding: "18px 0", borderRadius: 16, border: "none",
      background: disabled ? "#1e293b" : "linear-gradient(135deg,#7c3aed,#4f46e5)",
      color: "#fff", fontFamily: P, fontWeight: 800, fontSize: 18,
      cursor: disabled ? "default" : "pointer", ...style,
    }}>
      {children}
    </button>
  );
}

// ── MAIN STUDENT PAGE ───────────────────────────────────────────────────────

type StudentView = "login" | "topics" | "learning";

export default function StudentPage() {
  const [view, setView]           = useState<StudentView>(() =>
    sessionStorage.getItem("student_id") ? "topics" : "login"
  );
  const [studentId, setStudentId] = useState(() => sessionStorage.getItem("student_id") || "");
  const [unitId, setUnitId]       = useState("");
  const [topic, setTopic]         = useState("");

  function onLogin(name: string) {
    sessionStorage.setItem("student_id", name);
    setStudentId(name);
    setView("topics");
  }

  function onSelectTopic(uid: string, t: string) {
    setUnitId(uid);
    setTopic(t);
    setView("learning");
  }

  if (view === "login")    return <LoginScreen onLogin={onLogin} />;
  if (view === "topics")   return <TopicSelect studentId={studentId} onSelect={onSelectTopic} />;
  if (view === "learning") return (
    <LearningLoop
      studentId={studentId}
      unitId={unitId}
      topic={topic}
      onDone={() => setView("topics")}
    />
  );
  return null;
}

