"""
LLM content generator using Groq.
Generates all 7 content types for a subtopic.
Quality requirements:
- main_explanation: 2 clear sentences, simple words, teaches the core concept
- simple_explanation: 1 sentence, even simpler rephrase for re-teaching
- example: 1 analogy sentence starting with "It is like..."
- prerequisite: 1 sentence on what to know first
- hint: 1 sentence nudge (does NOT give away the answer)
- question: MCQ 4 options, all plausible, only one correct, short options
- easy_question: simpler MCQ for after re-teach, even more obvious correct answer
"""

import os, json
from groq import Groq
from dotenv import load_dotenv

load_dotenv()

GROQ_API_KEY = os.getenv("GROQ_API_KEY", "")
GROQ_MODEL   = os.getenv("GROQ_MODEL", "llama3-8b-8192")

client = Groq(api_key=GROQ_API_KEY)

SYSTEM_PROMPT = """You are an expert educator creating content for an adaptive learning platform.
Your students have low reading ability, so you must:
- Use very simple, clear English words
- Keep explanations SHORT but ACCURATE — no vague filler
- Make MCQ options ALL plausible (wrong answers should be believable, not silly)
- Never repeat the correct answer word-for-word in the question
- Always return valid JSON only — no markdown, no extra text
"""

def _call(prompt: str) -> dict:
    resp = client.chat.completions.create(
        model=GROQ_MODEL,
        messages=[
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user",   "content": prompt},
        ],
        temperature=0.3,
        response_format={"type": "json_object"},
    )
    return json.loads(resp.choices[0].message.content)


def generate_all(topic: str, subtopic: str) -> dict:
    prompt = f"""
Create complete learning content for the subtopic: "{subtopic}"
This subtopic belongs to the broader topic: "{topic}"

Return a JSON object with EXACTLY these 7 keys:

{{
  "main_explanation": {{
    "text": "Write exactly 2 sentences that clearly explain what {subtopic} is and why it matters. Use simple words a 12-year-old can understand. Be specific and accurate — not vague.",
    "emoji": "Pick one relevant emoji that best represents {subtopic}"
  }},

  "simple_explanation": {{
    "text": "Write exactly 1 sentence that explains {subtopic} in the simplest possible way. This is shown when a student gets the question wrong — so rephrase the concept completely differently from main_explanation.",
    "emoji": "Pick one relevant emoji"
  }},

  "example": {{
    "text": "Write exactly 1 sentence starting with 'It is like ' — give a real-world analogy that makes {subtopic} easy to picture. The analogy must be something students know from daily life.",
    "emoji": "Pick one emoji for the analogy"
  }},

  "prerequisite": {{
    "text": "Write exactly 1 sentence about the simpler concept a student must already understand before learning {subtopic}. Be specific about what that concept is.",
    "emoji": "📌"
  }},

  "hint": {{
    "text": "Write exactly 1 sentence that nudges the student toward the correct answer without giving it away. Reference a key property of {subtopic}.",
    "emoji": "💡"
  }},

  "question": {{
    "text": "Write a clear question testing understanding of {subtopic}. Do NOT use the words from the correct answer in the question itself.",
    "options": [
      "Correct answer — specific and accurate, 3-6 words",
      "Wrong answer — plausible but incorrect, same length",
      "Wrong answer — plausible but incorrect, same length",
      "Wrong answer — plausible but incorrect, same length"
    ],
    "correct": 0,
    "explanation": "Write 1-2 sentences explaining WHY the correct answer is correct and why the concept works this way."
  }},

  "easy_question": {{
    "text": "Write a simpler, more direct question about {subtopic}. This is shown after re-teaching — make the correct answer more obvious from the explanation.",
    "options": [
      "Correct answer — very clear and direct, 3-6 words",
      "Wrong answer — clearly different category",
      "Wrong answer — clearly different category",
      "Wrong answer — clearly different category"
    ],
    "correct": 0,
    "explanation": "Write 1 sentence explaining the correct answer simply."
  }}
}}

IMPORTANT RULES:
1. "correct" must always be 0 (first option is always correct — the frontend will shuffle)
2. All 4 options must be the same type of thing (e.g. all processes, or all devices — not a mix)
3. Options should be 3-6 words each — no full sentences as options
4. The main_explanation must be genuinely educational, not just a definition
5. Topic context for accuracy: {topic} → {subtopic}
"""
    result = _call(prompt)

    # Safety: shuffle options so correct isn't always first
    import random
    for qkey in ("question", "easy_question"):
        if qkey in result and "options" in result[qkey]:
            q = result[qkey]
            correct_text = q["options"][q["correct"]]
            random.shuffle(q["options"])
            q["correct"] = q["options"].index(correct_text)

    return result


def generate_fallback(topic: str, subtopic: str) -> dict:
    """High-quality fallback when Groq is unavailable — uses Computer Networks examples."""
    import random

    examples = {
        "Hosts and access networks": {
            "main_explanation": {
                "text": "A host is any device that sends or receives data on the internet, like your phone or laptop. An access network is the connection that links your device to the rest of the internet.",
                "emoji": "🖥️"
            },
            "simple_explanation": {
                "text": "Hosts are the devices people use, and access networks are the cables or Wi-Fi that connect them to the internet.",
                "emoji": "📡"
            },
            "example": {
                "text": "It is like a house (host) connected to the road network (access network) so people can travel in and out.",
                "emoji": "🏠"
            },
            "prerequisite": {
                "text": "You should first understand what the internet is — a global network connecting millions of devices.",
                "emoji": "📌"
            },
            "hint": {
                "text": "Think about what device you use to go online, and what physically connects it to the internet.",
                "emoji": "💡"
            },
            "question": {
                "text": "What is the role of an access network?",
                "options": ["Connects hosts to the internet", "Stores website data", "Creates new IP addresses", "Manages email servers"],
                "correct": 0,
                "explanation": "An access network is the last-mile connection that links end devices (hosts) like your laptop or phone to the broader internet infrastructure."
            },
            "easy_question": {
                "text": "Which of these is an example of a host device?",
                "options": ["A laptop sending emails", "A telephone pole", "A traffic light", "A water pipe"],
                "correct": 0,
                "explanation": "A laptop is a host because it sends and receives data directly on the internet."
            }
        }
    }

    if subtopic in examples:
        return examples[subtopic]

    # Generic fallback for any subtopic
    opts_q = [
        f"Core function of {subtopic}",
        f"A type of network protocol",
        f"A hardware component",
        f"A storage mechanism"
    ]
    opts_eq = ["Yes, it is part of " + topic, "No, it is unrelated", "Only sometimes", "Not defined yet"]
    random.shuffle(opts_q)
    random.shuffle(opts_eq)

    return {
        "main_explanation": {
            "text": f"{subtopic} is a key concept in {topic}. It defines how data or signals are handled in a specific part of the network.",
            "emoji": "📚"
        },
        "simple_explanation": {
            "text": f"{subtopic} is the part of {topic} that controls how information moves from one place to another.",
            "emoji": "💡"
        },
        "example": {
            "text": f"It is like a post office sorting letters — {subtopic} decides how each piece of data gets to the right destination.",
            "emoji": "📮"
        },
        "prerequisite": {
            "text": f"Before learning {subtopic}, you should understand the basic idea of how {topic} works as a system.",
            "emoji": "📌"
        },
        "hint": {
            "text": f"Think about the main job that {subtopic} performs and what would break if it didn't exist.",
            "emoji": "💡"
        },
        "question": {
            "text": f"What is the primary purpose of {subtopic} in {topic}?",
            "options": opts_q,
            "correct": opts_q.index(f"Core function of {subtopic}"),
            "explanation": f"{subtopic} serves as the core mechanism in {topic} for handling data flow and network communication."
        },
        "easy_question": {
            "text": f"Is {subtopic} a part of {topic}?",
            "options": opts_eq,
            "correct": opts_eq.index("Yes, it is part of " + topic),
            "explanation": f"Yes, {subtopic} is a fundamental part of {topic}."
        }
    }

